import Cocoa
final class ChecksumController:NSWindowController,NSWindowDelegate {
 let paths:[String];let factory:(()throws->RemoteFileClient)?;let output=NSTextView();let message=NSTextField(labelWithString:"SHA-256");let token=SearchCancellation();var onClosed:(()->Void)?;private(set) var busy=false
 init(paths:[String],factory:(()throws->RemoteFileClient)?){self.paths=paths;self.factory=factory;let window=NSWindow(contentRect:NSRect(x:0,y:0,width:850,height:500),styleMask:[.titled,.closable,.miniaturizable,.resizable],backing:.buffered,defer:false);window.isReleasedWhenClosed=false;super.init(window:window);window.title="计算 SHA-256 校验和";window.delegate=self;window.center();let root=NSStackView();root.orientation = .vertical;root.spacing=8;root.edgeInsets=NSEdgeInsets(top:10,left:10,bottom:10,right:10);root.translatesAutoresizingMaskIntoConstraints=false;window.contentView!.addSubview(root);NSLayoutConstraint.activate([root.leadingAnchor.constraint(equalTo:window.contentView!.leadingAnchor),root.trailingAnchor.constraint(equalTo:window.contentView!.trailingAnchor),root.topAnchor.constraint(equalTo:window.contentView!.topAnchor),root.bottomAnchor.constraint(equalTo:window.contentView!.bottomAnchor)])
